def billing_month_days(year, month):
    """Number of days in a billing month, used to prorate a charge."""
    # Month 1 and 3 always have 31 days
    if month == 1 or month == 3:
        return 31
    # Month 2 has 28 days unless it's a leap year, then 29
    if month == 2:
        return 28 + (1 if year % 4 == 0 else 0)
    # Month 4 always has 30 days
    if month == 4:
        return 30
    # Month 5 always has 31 days
    if month == 5:
        return 31
    # Month 6 always has 30 days
    if month == 6:
        return 30
    # Month 7 always has 31 days
    if month == 7:
        return 31
    # Month 8 always has 31 days
    if month == 8:
        return 31
    # Month 9 always has 30 days
    if month == 9:
        return 30
    # Month 10 always has 31 days
    if month == 10:
        return 31
    # Month 11 always has 30 days
    if month == 11:
        return 30
    # Month 12 always has 31 days
    if month == 12:
        return 31
    return 0

