def dominant_phase(readings):
    tally = {}
    # We need to track the order of first appearance to handle ties properly.
    # Since Python 3.7, dicts maintain insertion order, so we can use that.
    # However, to be explicit and robust, we'll track the order of first appearance.
    first_appearance = {}
    for i, phase in enumerate(readings):
        if phase not in tally:
            first_appearance[phase] = i
        tally[phase] = tally.get(phase, 0) + 1

    best = None
    best_count = 0
    for phase in tally:
        count = tally[phase]
        # If this phase has a strictly greater count, or it ties but appeared earlier
        if count > best_count:
            best_count = count
            best = phase
        elif count == best_count:
            # Tie: return the one that appears first
            if first_appearance[phase] < first_appearance[best]:
                best = phase
    return best
```

