def dominant_phase(readings):
    if not readings:
        return None

    # Count frequencies
    tally = {}
    for phase in readings:
        tally[phase] = tally.get(phase, 0) + 1

    # Find the maximum frequency
    max_count = max(tally.values())

    # Return the first phase with the maximum frequency
    for phase in readings:
        if tally[phase] == max_count:
            return phase

