def badge_color(hue, sat, val):
    # HSV to RGB conversion based on colorsys.hsv_to_rgb logic
    # hue: 0.0-1.0 (color wheel position)
    # sat: 0.0-1.0 (saturation, 0.0 = no saturation, 1.0 = saturated)
    # val: 0.0-1.0 (base value)

    if sat == 0.0:
        # No saturation: just use val for all components
        return val, val, val

    # Scale hue to 0-5 for a 6-segment wheel
    i = int(hue * 6.0)
    f = (hue * 6.0) - i

    # Base value for saturation
    # sat represents how much of the color is "saturated" (painted with full intensity)
    # val is the base

    # Calculate the three components based on hue segment
    # The original colorsys.hsv_to_rgb uses a 6-segment wheel:
    # segments: 0, 1, 2, 3, 4, 5
    # Each segment has a specific pattern of (r, g, b) mixing

    # Calculate intermediate values
    # p = val * (1 - sat) -> the unsaturated part
    # q and t are used for interpolation

    p = val * (1.0 - sat)
    q = val * (1.0 - sat * f)
    t = val * (1.0 - sat * (1.0 - f))

    # Wrap i to 0-5 range
    i = i % 6

    if i == 0:
        return (val, t, p)
    elif i == 1:
        return (q, val, p)
    elif i == 2:
        return (p, val, t)
    elif i == 3:
        return (p, q, val)
    elif i == 4:
        return (t, val, p)
    else:  # i == 5
        return (val, p, q)
