def badge_color(hue, sat, val):
    """
    Maps an HSV colour triple (hue, saturation, value) to an RGB triple.

    Each argument is a float between 0.0 and 1.0.
    The function reproduces the behaviour of colorsys.hsv_to_rgb.

    Returns:
        A tuple (r, g, b) of floats between 0.0 and 1.0.
    """
    # Handle saturation == 0.0 case: return (val, val, val)
    # This matches the original behavior where sat=0 leads to uniform color
    if sat == 0.0:
        return (val, val, val)

    # Calculate intermediate values based on hue and saturation
    i = int(hue * 6.0)
    f = (hue * 6.0) - i

    # p, q, t are calculated based on val and sat
    p = val * (1.0 - sat)
    q = val * (1.0 - sat * f)
    t = val * (1.0 - sat * (1.0 - f))

    # Map i to specific RGB components
    i = i % 6

    if i == 0:
        return (val, t, p)
    elif i == 1:
        return (q, val, p)
    elif i == 2:
        return (p, val, t)
    elif i == 3:
        return (p, q, val)
    elif i == 4:
        return (t, val, p)
    else:  # i == 5
        return (val, p, q)
