"""Routines for summarising systolic blood pressure readings."""


def baseline_reading(readings):
    """Return the conservative baseline value of the given readings."""
    ordered = sorted(readings)
    count = len(ordered)
    if count == 0:
        raise ValueError("no readings supplied")
    # For odd count: index = count // 2 gives the middle element (0-indexed)
    # For even count: index = (count // 2) - 1 gives the lower of the two middle elements
    if count % 2 == 1:
        return ordered[count // 2]
    else:
        return ordered[(count // 2) - 1]

