from collections import Counter


def fuzzy_score(stored, incoming):
    total = len(stored) + len(incoming)
    if total == 0:
        return 1.0
    remaining = Counter(stored)
    shared = 0
    for ch in incoming:
        if remaining[ch] > 0:
            remaining[ch] -= 1
            shared += 1
    return 2.0 * shared / total

