import solution
import unittest


class TestCalibratedMedian(unittest.TestCase):
    def test_empty_raises_error(self):
        with self.assertRaises(ValueError):
            solution.calibrated_median([])

    def test_single_element(self):
        self.assertEqual(solution.calibrated_median([5]), 5)

    def test_two_elements_even(self):
        self.assertEqual(solution.calibrated_median([1, 10]), 10 / 2)

    def test_three_elements_odd(self):
        self.assertEqual(solution.calibrated_median([1, 5, 10]), 5)

    def test_four_elements_even(self):
        self.assertEqual(solution.calibrated_median([1, 5, 10, 15]), (5 + 10) / 2)

    def test_negative_values(self):
        self.assertEqual(solution.calibrated_median([-10, -5, 5, 10]), (-5 + 5) / 2)

    def test_duplicate_values(self):
        self.assertEqual(solution.calibrated_median([5, 5, 5]), 5)


if __name__ == '__main__':
    unittest.main()

