    """Count how often each whitespace-separated word of text occurs."""
    tally = {}
    word = ""
    for ch in text:
        if ch.isspace():
            if word:
                tally[word] = tally.get(word, 0) + 1
                word = ""
        else:
            word += ch
    # Handle the last word if text doesn't end with whitespace
    if word:
        tally[word] = tally.get(word, 0) + 1
    return tally
