import billing

def test_median_odd():
    assert billing.median_invoice([5]) == 5
    assert billing.median_invoice([1, 3, 7]) == 3
    assert billing.median_invoice([1, 5, 7]) == 5
    assert billing.median_invoice([1, 10, 100]) == 10

def test_median_even():
    assert billing.median_invoice([1, 2]) == 1.0
    assert billing.median_invoice([1, 2, 3, 4]) == 2.0
    assert billing.median_invoice([1, 10, 100, 1000]) == (10 + 100) / 2

def test_median_empty():
    try:
        billing.median_invoice([])
        assert False, "Expected ValueError"
    except ValueError:
        pass

