import unittest
from usage import pulses_to_m3, water_bill


class TestUsage(unittest.TestCase):
    def test_pulses_to_m3_4000(self):
        """A garden meter reading of 4000 pulses is 800 L, i.e. 0.8 m3."""
        self.assertAlmostEqual(pulses_to_m3(4000), 0.8)

    def test_pulses_to_m3_15000(self):
        """pulses_to_m3(15000) should return 3.0, not 3000.0."""
        self.assertAlmostEqual(pulses_to_m3(15000), 3.0)

    def test_water_bill_15000_3(self):
        """water_bill(15000, 3) should return 9.0, not 9000.0."""
        self.assertAlmostEqual(water_bill(15000, 3), 9.0)

    def test_pulses_to_m3_zero(self):
        """Edge case: zero pulses should return zero m3."""
        self.assertAlmostEqual(pulses_to_m3(0), 0.0)

    def test_water_bill_zero(self):
        """Edge case: zero pulses with any rate should return zero."""
        self.assertAlmostEqual(water_bill(0, 1.0), 0.0)

    def test_water_bill_negative(self):
        """Edge case: negative pulses should return negative m3."""
        self.assertAlmostEqual(water_bill(-15000, 3), -9.0)


if __name__ == '__main__':
    unittest.main()

