import unittest
from tournament import first_round


class TestFirstRound(unittest.TestCase):
    def test_empty(self):
        """Test with 0 players."""
        self.assertEqual(first_round(0), [])

    def test_one_player(self):
        """Test with 1 player."""
        self.assertEqual(first_round(1), [])

    def test_two_players(self):
        """Test with 2 players."""
        self.assertEqual(first_round(2), [1, 2])

    def test_four_players(self):
        """Test with 4 players."""
        self.assertEqual(first_round(4), [(1, 2), (3, 4)])

    def test_eight_players(self):
        """Test with 8 players - the main bug case."""
        result = first_round(8)
        expected = [(1, 8), (4, 5), (2, 7), (3, 6)]
        self.assertEqual(result, expected)

    def test_six_players(self):
        """Test with 6 players."""
        result = first_round(6)
        expected = [(1, 6), (2, 5), (3, 4)]
        self.assertEqual(result, expected)

    def test_type_is_list(self):
        """Ensure the return type is a list."""
        result = first_round(2)
        self.assertIsInstance(result, list)

    def test_elements_are_tuples(self):
        """Ensure elements are tuples for n >= 2."""
        result = first_round(4)
        for item in result:
            self.assertIsInstance(item, tuple)


if __name__ == '__main__':
    unittest.main()

