from likert_scale import parse_response


def average_rating(tokens):
    ratings = []
    for t in tokens:
        try:
            val = parse_response(t)
            # Only accept valid ratings (1-5)
            if 1 <= val <= 5:
                ratings.append(val)
        except Exception:
            # Skip invalid tokens
            continue

    if not ratings:
        return 0.0

    return sum(ratings) / len(ratings)

