        """Test with two labels where the first is older."""
        self.assertEqual(most_recent_snapshot(['bkp-2023-01-01', 'bkp-2023-03-15']), 'bkp-2023-01-01')

    def test_two_labels_unsorted(self):
        """Test with two labels where the second is older."""
        self.assertEqual(most_recent_snapshot(['bkp-2023-03-15', 'bkp-2023-01-01']), 'bkp-2023-01-01')

    def test_three_labels(self):
        """Test with three labels as per the requirement."""
        labels = ['bkp-2023-01-01', 'bkp-2023-03-15', 'bkp-2023-02-10']
