        """Test with three labels in different order."""
        labels = ['bkp-2023-03-15', 'bkp-2023-02-10', 'bkp-2023-01-01']
        self.assertEqual(most_recent_snapshot(labels), 'bkp-2023-01-01')

    def test_empty_labels(self):
        """Test with empty labels list."""
        with self.assertRaises(IndexError):
            most_recent_snapshot([])


if __name__ == '__main__':
