def review_ratio(text, default=None):
    # Return default for None, empty or whitespace-only text
    if text is None or (isinstance(text, str) and text.strip() == ''):
        return default

    # Check if text contains exactly one slash
    if not isinstance(text, str) or text.count('/') != 1:
        return default

    # Split by slash
    parts = text.split('/')
    if len(parts) != 2:
        return default

    num_str, den_str = parts

    # Check if parts are integers (strip whitespace and check)
    try:
        num = int(num_str.strip())
        den = int(den_str.strip())
    except (ValueError, AttributeError):
        return default

    # Check for zero denominator
    if den == 0:
        return default

    # Return the fraction as a float
    return float(num) / float(den)
