def review_ratio(text, default=None):
    # Handle None, empty, or whitespace-only text
    if text is None or not text.strip():
        return default

    # Split by '/' and check for exactly one slash (i.e., two parts)
    parts = text.split('/')
    if len(parts) != 2:
        return default

    num_str, den_str = parts

    # Strip whitespace and check if parts are valid integers
    num_str = num_str.strip()
    den_str = den_str.strip()

    # Check for empty parts after stripping
    if not num_str or not den_str:
        return default

    try:
        num = int(num_str)
        den = int(den_str)
    except ValueError:
        return default

    # Check for zero denominator
    if den == 0:
        return default

    return float(num) / float(den)
