def leg_minutes(text, default=0):
    # Handle None or non-string input
    if text is None or not isinstance(text, str):
        return default

    s = text.strip()
    # Handle empty or whitespace-only text
    if not s:
        return default

    # Must have a space to separate route from duration
    if ' ' not in s:
        return default

    # Split into route and duration parts
    parts = s.rsplit(' ', 1)
    if len(parts) != 2:
        return default

    route, dur = parts

    hours = 0
    minutes = 0

    # Parse hours if present
    if 'h' in dur:
        head, dur = dur.split('h', 1)
        try:
            hours = int(head)
        except ValueError:
            return default

    # Parse minutes if present
    dur = dur.strip()
    if dur.endswith('m'):
        try:
            minutes = int(dur[:-1])
        except ValueError:
            return default
    elif dur:
        # If there's remaining text that doesn't end with 'm', it's malformed
        return default

    return hours * 60 + minutes
