def leg_minutes(text, default=0):
    # Handle None, non-string, or empty/whitespace-only text
    if text is None or not isinstance(text, str):
        return default

    s = text.strip()
    if not s or ' ' not in s:
        return default

    # Split to get the duration part
    # The format is like "ROUTE DURATION" e.g. "JFK->LAX 5h30m"
    # We need to find the last space to separate route from duration
    try:
        # Find the last space
        last_space_idx = s.rfind(' ')
        if last_space_idx == -1:
            return default
        route = s[:last_space_idx]
        dur = s[last_space_idx + 1:]
    except Exception:
        return default

    # Clean up duration
    dur = dur.strip()
    if not dur:
        return default

    hours = 0
    minutes = 0

    # Check if there's an hour component
    if 'h' in dur:
        # Split by 'h'
        parts = dur.split('h', 1)
        head = parts[0]
        remainder = parts[1]

        try:
            hours = int(head)
        except ValueError:
            return default

        # Process the remainder for minutes
        remainder = remainder.strip()
        if remainder.endswith('m'):
            try:
                minutes = int(remainder[:-1])
            except ValueError:
                return default
        elif remainder:
            return default
        else:
            # No minutes specified, only hours
            minutes = 0
    elif dur.endswith('m'):
        # No hours, just minutes
        try:
            minutes = int(dur[:-1])
        except ValueError:
            return default
    else:
        # Malformed
        return default

    return hours * 60 + minutes
