def parse_slot_id(header, default=None):
    """
    Parse a slot ID from a header string.

    Handles cases like:
    - 'slot:3' -> 3
    - '7' -> 7
    - ' 7 ' -> 7
    - None, empty, whitespace-only -> default
    - Non-string values -> default
    - Malformed headers like 'slot:x' or 'banana' -> default
    """
    if header is None or not isinstance(header, str):
        return default

    s = header.strip()
    if not s:
        return default

    # Check for malformed header that contains ':' but the part after ':' is not an integer
    if ':' in s:
        parts = s.split(':', 1)
        # parts[0] is the label (like 'slot'), parts[1] is the value
        value_part = parts[1].strip()
        if not value_part:
            return default
        try:
            return int(value_part)
        except ValueError:
            return default
    else:
        # No colon, try to parse the whole string as integer
        try:
            return int(s)
        except ValueError:
            return default
