        # We only accept int and float here; list, dict, etc. will be rejected
        if not isinstance(points, (int, float)):
            return default
        # Check for NaN or infinity which are technically float/int but not valid for ranking
        import math
        if isinstance(points, float) and (math.isnan(points) or math.isinf(points)):
            return default

