import re

def lift_wait(text, default=0):
    # Handle None, non-string, or empty/whitespace-only strings
    if text is None or not isinstance(text, str):
        return default

    cleaned = text.strip().lower()

    # If the string becomes empty after stripping, return default
    if not cleaned:
        return default

    # Remove 'min' (case-insensitive) from the string
    cleaned = cleaned.replace('min', '')

    # Try to find the first integer in the cleaned string
    match = re.search(r'(\d+)', cleaned)
    if match:
        try:
            return int(match.group(1))
        except ValueError:
            return default
    else:
        return default
