def to_csv_field(value, default=""):
    """
    Returns a CSV-safe field for a single value.
    - None and empty strings return default.
    - Strings are stripped; if the result is empty, return default.
    - Ints and floats become str(value).
    - Any other type (e.g. list, dict) raises TypeError.
    - If the string contains comma, double quote, or newline, it is wrapped
      in double quotes with internal quotes doubled.
    """
    if value is None or value == "":
        return default
    if isinstance(value, (int, float)):
        return str(value)
    if not isinstance(value, str):
        raise TypeError(f"Unsupported type: {type(value).__name__}")

    text = value.strip()
    if text == "":
        return default

    if ',' in text or '"' in text or '\n' in text:
        return '"' + text.replace('"', '""') + '"'
    return text

