def parse_printer_job(raw, default=None):
    # Check for None, empty, or whitespace-only text
    if raw is None or (isinstance(raw, str) and raw.strip() == ''):
        return default

    # Raise TypeError for non-string values (int, list, dict, etc.)
    if not isinstance(raw, str):
        raise TypeError("Expected a string")

    # Strip whitespace and split by ':'
    parts = raw.strip().split(":")

    # Check for correct number of fields
    if len(parts) != 3:
        return default

    user, doc, copies = parts

    # Check for empty user or document
    if not user or not doc:
        return default

    # Check for valid integer copies
    try:
        copies_int = int(copies)
    except ValueError:
        return default

    return (user, doc, copies_int)

