def grid_rows(text, default=None):
    """
    Parses a crossword grid given as text into a tuple of equal-length row strings.

    Returns default for None, empty, whitespace-only text, or non-string input.
    Raises ValueError if rows have different lengths.
    """
    # Return default for None, non-string, empty, or whitespace-only text
    if text is None or not isinstance(text, str):
        return default

    if not text.strip():
        return default

    # Split into lines and strip trailing whitespace (but keep leading/trailing spaces within the row if they are part of the grid)
    # Actually, per the original code: rstrip() removes trailing whitespace from each line
    lines = [ln.rstrip() for ln in text.strip().splitlines()]

    # Check that all lines have the same length
    if len(lines) > 0:
        first_len = len(lines[0])
        for line in lines:
            if len(line) != first_len:
                raise ValueError("Rows have different lengths")

    return tuple(lines)
