def probe_temp(reading, default=None):
    """Convert a compost probe reading like '58.4 C' to degrees Celsius."""
    # Handle None input
    if reading is None:
        return default

    # Handle non-string inputs (e.g., numbers, booleans, etc.)
    if not isinstance(reading, str):
        return default

    s = reading.strip()
    if not s:
        return default

    # Remove trailing 'C' or 'c' if present
