    def test_valid_with_m_suffix(self):
        self.assertEqual(solution.backoff_seconds("1m"), 60.0)

    def test_none_returns_default(self):
        self.assertIsNone(solution.backoff_seconds(None))
        self.assertEqual(solution.backoff_seconds(None, 10), 10)

    def test_empty_string_returns_default(self):
        self.assertIsNone(solution.backoff_seconds(""))
        self.assertEqual(solution.backoff_seconds("", 5), 5)

