def backoff_seconds(spec, default=None):
    """
    Convert a backoff time string to seconds.

    Supports suffixes: 'ms' (milliseconds), 's' (seconds), 'm' (minutes).
    If no suffix is present, the value is treated as seconds.

    Examples:
        '2.5s' -> 2.5
        '500ms' -> 0.5 (500 milliseconds = 0.5 seconds)
        '1m' -> 60.0
        '3' -> 3.0
        ' 0.25 s ' -> 0.25

    Returns default for None, empty string, whitespace-only, or malformed specs.
    Raises TypeError for non-string inputs.
    """
    if not isinstance(spec, str):
        raise TypeError("spec must be a string")

    if spec is None or spec.strip() == "":
        return default

    s = spec.strip().lower()

    # Check for known suffixes
    for suffix, factor in (("ms", 0.001), ("s", 1.0), ("m", 60.0)):
        if s.endswith(suffix):
            try:
                value_str = s[:-len(suffix)]
                return float(value_str) * factor
            except ValueError:
                return default

    # If no suffix matched, try to parse as a plain number
    try:
        return float(s)
    except ValueError:
        return default

