def backoff_seconds(spec, default=None):
    """Convert a retry backoff string to seconds.

    Args:
        spec: A string like '2.5s', '500ms', '1m', '3' or ' 0.25 s '.
        default: The default value to return for None, empty, whitespace-only, or malformed specs.

    Returns:
        The delay in seconds as a float, or default if spec is None, empty, whitespace-only, or malformed.

    Raises:
        TypeError: If spec is not a string.
    """
    if spec is None:
        return default
    if not isinstance(spec, str):
        raise TypeError("spec must be a string")
    if spec == "":
        return default

    s = spec.strip().lower()
    if s == "":
        return default

    for suffix, factor in (("ms", 0.001), ("s", 1.0), ("m", 60.0)):
        if s.endswith(suffix):
            try:
                return float(s[:-len(suffix)]) * factor
            except ValueError:
                return default
            except TypeError:
                return default

    try:
        return float(s)
    except ValueError:
        return default
