def backoff_seconds(spec, default=None):
    """
    Convert a backoff string into seconds.

    Examples:
        '2.5s' -> 2.5
        '500ms' -> 0.5 (milliseconds to seconds)
        '1m' -> 60.0 (minutes to seconds)
        '3' -> 3.0
        ' 0.25 s ' -> 0.25

    Returns default for None, empty string, whitespace-only, or malformed specs.
    Raises TypeError for non-string inputs.
    """
    if not isinstance(spec, str):
        raise TypeError("spec must be a string")

    if spec is None or spec.strip() == "":
        return default

    s = spec.strip().lower()

    # Try each suffix
    for suffix, factor in (("ms", 0.001), ("s", 1.0), ("m", 60.0)):
        if s.endswith(suffix):
            try:
                num = float(s[:-len(suffix)])
                return num * factor
            except ValueError:
                return default

    # No suffix found, try to parse as a number
    try:
        return float(s)
    except ValueError:
        return default
