    """Convert a retry backoff string to seconds.

    Supports suffixes: 'ms' (milliseconds), 's' (seconds), 'm' (minutes).
    If no suffix is provided, the value is treated as seconds.

    Returns default for None, empty string, whitespace-only text, or malformed specs.
    Raises TypeError for non-string inputs.
    """
    if not isinstance(spec, str):
        raise TypeError("spec must be a string")

    if spec is None or spec == "":
        return default

    s = spec.strip().lower()

    if not s:
        return default

    # Check for valid suffixes
    for suffix, factor in (("ms", 0.001), ("s", 1.0), ("m", 60.0)):
        if s.endswith(suffix):
            try:
                value = float(s[:-len(suffix)])
                return value * factor
            except ValueError:
                return default

    # No suffix matched, try to parse as float (treat as seconds)
    try:
        return float(s)
    except ValueError:
        return default
