# tally_sheet.py

def record_ballots(path, candidate, ballots):
    """Append a CSV line 'candidate,ballots' to the tally file.

    Creates the file with a header row if it does not exist or is empty.
    """
    import os

    # Check if file exists and has content
    if os.path.exists(path) and os.path.getsize(path) > 0:
        # File exists and has content, just append
        with open(path, 'a', encoding='utf-8') as f:
            f.write(f'{candidate},{ballots}\n')
    else:
        # File does not exist or is empty, create with header
        with open(path, 'w', encoding='utf-8') as f:
            f.write('candidate,ballots\n')
            f.write(f'{candidate},{ballots}\n')


def read_tally(path):
    """Return a dict mapping each candidate to the sum of their ballots.

    Ignores the header row. Returns {} when the file is missing.
    """
    try:
        with open(path, encoding='utf-8') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        return {}

    tally = {}
    # Skip header row (index 0)
    for line in lines[1:]:
        if not line:
            continue
        name, count = line.split(',')
        tally[name] = tally.get(name, 0) + int(count)
    return tally

