    # Check if the file needs a header
    create_header = False
    if not os.path.exists(path):
        create_header = True
    else:
        # Check if the file is empty
        with open(path, 'r', encoding='utf-8') as f:
            first_line = f.readline().strip()
            if not first_line or first_line != 'candidate,ballots':
                create_header = True

    mode = 'a'
    if create_header:
        # Write header and then the first record
        with open(path, 'w', encoding='utf-8') as f:
            f.write('candidate,ballots\n')
            f.write(f'{candidate},{ballots}\n')
        return

    # Append to existing file
    with open(path, 'a', encoding='utf-8') as f:
        f.write(f'{candidate},{ballots}\n')


def read_tally(path):
    """Return a dict mapping each candidate to the sum of their ballots,
    ignoring the header row, and return {} when the file is missing.
    """
    try:
        with open(path, encoding='utf-8') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        return {}

    tally = {}
    # Skip the header row if it exists
    for line in lines:
        # Skip header
        if line.startswith('candidate,'):
            continue
        # Skip empty lines
        if not line:
            continue
        parts = line.split(',')
        if len(parts) >= 2:
            name = parts[0]
            try:
                count = int(parts[1])
            except ValueError:
                continue
            tally[name] = tally.get(name, 0) + count
    return tally

