    write_header = not os.path.exists(path) or os.path.getsize(path) == 0
    with open(path, 'a', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        if write_header:
            w.writerow(HEADER)
        w.writerow([systolic, diastolic, pulse])


def load_readings(path):
    try:
        with open(path, newline='', encoding='utf-8') as f:
            rows = list(csv.reader(f))
    except FileNotFoundError:
        return []
    if not rows:
        return []
    # Skip the header row if it exists and matches the expected header
    if rows[0] == HEADER:
        rows = rows[1:]
    return [(int(s), int(d), int(p)) for s, d, p in rows]

