# auction_ledger.py

def record_bid(path, item, bidder, amount):
    with open(path, 'a', newline='', encoding='utf-8') as f:
        f.write(f'{item},{bidder},{amount:.2f}\n')


def all_bids(path):
    try:
        with open(path, encoding='utf-8') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        return []
    bids = []
    for line in lines:
        if not line.strip():
            continue
        item, bidder, amount = line.split(',')
        bids.append((item, bidder, float(amount)))
    return bids


def top_bidder(path, item):
    placed = [b for b in all_bids(path) if b[0] == item]
    if not placed:
        return None
    return max(placed, key=lambda b: b[2])[1]

