import os

def enqueue(path, job_name, minutes):
    write_header = not os.path.exists(path)
    with open(path, 'a', encoding='utf-8') as f:
        if write_header:
            f.write('name,minutes\n')
        f.write(f'{job_name},{minutes}\n')


def queue(path):
    try:
        with open(path, encoding='utf-8') as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        return []
    jobs = []
    for line in lines[1:]:
        name, mins = line.split(',')
        jobs.append((name, int(mins)))
    return sorted(jobs)
