import survey
import os
import tempfile


def test_save_load_empty():
    """Test saving an empty dict and loading it back."""
    with tempfile.NamedTemporaryFile(suffix='.csv', delete=False) as tmp:
        path = tmp.name
    try:
        survey.save_answers(path, {})
        result = survey.load_answers(path)
        assert result == {}, f"Expected empty dict, got {result}"
    finally:
        if os.path.exists(path):
            os.remove(path)


def test_save_load_nonempty():
    """Test saving a dict with answers and loading it back."""
    answers = {
        'What is your name?': 'Alice',
        'How old are you?': '25',
        'Where do you live?': 'Home'
    }
    with tempfile.NamedTemporaryFile(suffix='.csv', delete=False) as tmp:
        path = tmp.name
    try:
        survey.save_answers(path, answers)
        result = survey.load_answers(path)
        assert result == answers, f"Expected {answers}, got {result}"
    finally:
        if os.path.exists(path):
            os.remove(path)


def test_load_nonexistent():
    """Test loading a file that does not exist."""
    with tempfile.NamedTemporaryFile(suffix='.csv', delete=False) as tmp:
        path = tmp.name
    try:
        os.remove(path)  # Ensure it doesn't exist
        result = survey.load_answers(path)
        assert result == {}, f"Expected empty dict, got {result}"
    finally:
        if os.path.exists(path):
            os.remove(path)


def test_save_overwrites():
    """Test that save_answers overwrites an existing file."""
    answers1 = {'Q1': 'A1'}
    answers2 = {'Q2': 'A2'}
    with tempfile.NamedTemporaryFile(suffix='.csv', delete=False) as tmp:
        path = tmp.name
    try:
        survey.save_answers(path, answers1)
        survey.save_answers(path, answers2)
        result = survey.load_answers(path)
        assert result == answers2, f"Expected {answers2}, got {result}"
    finally:
        if os.path.exists(path):
            os.remove(path)


def test_save_load_special_chars():
    """Test saving and loading answers with special CSV characters."""
    answers = {'Question, with comma': 'Answer, with comma', 'Question "with quotes"': 'Answer "with quotes"'}
    with tempfile.NamedTemporaryFile(suffix='.csv', delete=False) as tmp:
        path = tmp.name
    try:
        survey.save_answers(path, answers)
        result = survey.load_answers(path)
        assert result == answers, f"Expected {answers}, got {result}"
    finally:
        if os.path.exists(path):
            os.remove(path)


def test_save_load_unicode():
    """Test saving and loading answers with unicode characters."""
    answers = {'Question with unicode: é, ñ, ß': 'Answer with unicode: é, ñ, ß'}
    with tempfile.NamedTemporaryFile(suffix='.csv', delete=False) as tmp:
