import csv


def save_answers(path, answers):
    with open(path, 'w', encoding='utf-8', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['question', 'answer'])
        for question in sorted(answers):
            writer.writerow([question, answers[question]])


def load_answers(path):
