def reserve(path, observer, target, night):
    # Check if the file exists and has content
    try:
        with open(path, 'r', encoding='utf-8') as f:
            content = f.read()
    except FileNotFoundError:
        content = ''

    with open(path, 'a', encoding='utf-8') as f:
        # If the file is empty or missing, write the header first
        if not content.strip():
            f.write('observer,target,night\n')
        f.write(f'{observer},{target},{night}\n')


def bookings(path):
    try:
        with open(path, encoding='utf-8') as f:
            rows = f.read().splitlines()
    except FileNotFoundError:
        return []

    # Skip the header line if it exists
    if rows and rows[0].strip() == 'observer,target,night':
        data_rows = rows[1:]
    else:
        data_rows = rows

    return [tuple(row.split(',')) for row in data_rows]

def reserve(path, observer, target, night):
    """Append a booking as a CSV data row to the file.

    Writes the header line only when the file is new or missing.
    """
    import os
    # Check if file exists and is not empty
    if os.path.exists(path) and os.path.getsize(path) > 0:
        with open(path, 'a', encoding='utf-8') as f:
            f.write(observer + ',' + target + ',' + str(night) + '\n')
    else:
        with open(path, 'w', encoding='utf-8') as f:
            f.write('observer,target,night\n')
            f.write(observer + ',' + target + ',' + str(night) + '\n')


def bookings(path):
    """Return the data rows as tuples of strings, or [] when the file does not exist."""
    try:
        with open(path, encoding='utf-8') as f:
            rows = f.read().splitlines()
    except FileNotFoundError:
        return []
    if not rows:
        return []
    return [tuple(row.split(',')) for row in rows[1:]]

