import unittest
from solution import top_words


class TestTopWords(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(top_words(""), [])

    def test_single_word(self):
        self.assertEqual(top_words("hello"), [("hello", 1)])

    def test_single_word_n_larger(self):
        self.assertEqual(top_words("hello", 5), [("hello", 1)])

    def test_multiple_words_same_count(self):
        result = top_words("a b c", 3)
        self.assertEqual(result, [("a", 1), ("b", 1), ("c", 1)])

    def test_multiple_words_different_counts(self):
        result = top_words("a a b c", 3)
        self.assertEqual(result, [("a", 2), ("b", 1), ("c", 1)])

    def test_case_insensitive(self):
        result = top_words("Hello hello HELLO", 3)
        self.assertEqual(result, [("hello", 3)])

    def test_punctuation_ignored(self):
        result = top_words("hello, world! hello.", 3)
        self.assertEqual(result, [("hello", 2), ("world", 1)])

    def test_mixed_case_with_punctuation(self):
        result = top_words("Hello, world! Hello world.", 3)
        self.assertEqual(result, [("hello", 2), ("world", 2)])


