sys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from solution import fine_for


class TestFineFor(unittest.TestCase):

    def test_simple_case(self):
        # days_late=1, daily_cents=25, grace_days=0 => should charge 25 cents
        self.assertEqual(fine_for(1), 25)

    def test_grace_days_skipped(self):
        # days_late=2, daily_cents=25, grace_days=1 => should charge 25 cents for 1 day after grace
        self.assertEqual(fine_for(2, grace_days=1), 25)

    def test_grace_days_skipped_with_more_days(self):
        # days_late=3, daily_cents=25, grace_days=1 => should charge 25 cents for 2 days after grace
        self.assertEqual(fine_for(3, grace_days=1), 25 * 2)

    def test_max_cents_capped(self):
        # days_late=10, daily_cents=25, grace_days=0 => should cap at 2000 (10 * 25 = 1000, capped at 2000)
        self.assertEqual(fine_for(10), 2000)

    def test_grace_days_and_max_cents(self):
        # days_late=10, daily_cents=25, grace_days=1 => 9 days after grace, 9*25=90, capped at 2000
        self.assertEqual(fine_for(10, daily_cents=25, grace_days=1), 2000)

    def test_zero_days_late(self):
        # days_late=0 => no days to charge
        self.assertEqual(fine_for(0), 0)

    def test_large_grace_days(self):
        # days_late=1, daily_cents=25, grace_days=5 => 1 day, 5 grace, 0 days after grace => 0
        self.assertEqual(fine_for(1, grace_days=5), 0)

    def test_custom_daily_cents(self):
        # days_late=1, daily_cents=5, grace_days=0 => should charge 5 cents
        self.assertEqual(fine_for(1, daily_cents=5), 5)


if __name__ == '__main__':
    unittest.main()

