from lib.calibkit import linear_map

SENSOR_LO = 0.5
SENSOR_HI = 4.5


def calibrate(raw):
    return round(linear_map(raw, SENSOR_LO, SENSOR_HI, 0.0, 100.0), 2)


def drift(raw, reference):
    return round(calibrate(raw) - calibrate(reference), 2)

def linear_map(value, in_lo, in_hi, out_lo, out_hi):
    """
    Maps a value from the input range [in_lo, in_hi] to the output range [out_lo, out_hi].
    Does NOT clamp the output to the range.
    """
    if in_hi == in_lo:
        return out_lo
    return out_lo + (value - in_lo) * (out_hi - out_lo) / (in_hi - in_lo)


SENSOR_LO = 0.5
SENSOR_HI = 4.5


def calibrate(raw):
    """
    Converts a raw sensor reading to a percentage of the sensor's input range [SENSOR_LO, SENSOR_HI] -> [0.0, 100.0].
    Rounded to 2 decimals.
    """
    mapped = linear_map(raw, SENSOR_LO, SENSOR_HI, 0.0, 100.0)
    return round(mapped, 2)


def drift(raw, reference):
    """
    Calculates the difference between the calibrated percentages of two sensor readings,
    rounded to 2 decimals.
    """
    return round(calibrate(raw) - calibrate(reference), 2)

