def window_width(window_text):
    start, end = parse_window(window_text)
    # Calculate the number of minutes in the delivery window
    # For a normal window (start <= end), the width is end - start
    # For an overnight window (start > end), the width is (1440 - start) + end
    if start <= end:
        return end - start
    else:
        return (1440 - start) + end


def fits_in_window(window_text, duration_minutes):
    start, end = parse_window(window_text)
    # Calculate the number of minutes in the delivery window
    if start <= end:
        window_minutes = end - start
    else:
        window_minutes = (1440 - start) + end

    return window_minutes >= duration_minutes
