import unittest
from solution import batch_plan


class TestBatchPlan(unittest.TestCase):
    def test_zero_flour_kg(self):
        self.assertEqual(batch_plan(0, 10, 3), [])

    def test_zero_flour_per_loaf(self):
        # If flour_per_loaf is 0, division by zero error is expected
        with self.assertRaises(ZeroDivisionError):
            batch_plan(10, 0, 3)

    def test_zero_trays(self):
        # If trays is 0, division by zero error is expected
        with self.assertRaises(ZeroDivisionError):
            batch_plan(10, 10, 0)

    def test_single_tray(self):
        self.assertEqual(batch_plan(10, 10, 1), [10])

    def test_single_loaf_single_tray(self):
        self.assertEqual(batch_plan(10, 1, 1), [1])

    def test_even_distribution(self):
        # 12 loaves, 3 trays -> [5, 5, 5]
        self.assertEqual(batch_plan(12, 1, 3), [5, 5, 5])

    def test_uneven_distribution(self):
        # 11 loaves, 3 trays -> [6, 5, 5] (larger loads first)
        self.assertEqual(batch_plan(11, 1, 3), [6, 5, 5])

    def test_more_loaves_than_trays(self):
        # 15 loaves, 3 trays -> [6, 6, 5] (larger loads first)
        self.assertEqual(batch_plan(15, 1, 3), [6, 6, 5])

    def test_fewer_loaves_than_trays(self):
        # 3 loaves, 3 trays -> [1, 1, 1]
        self.assertEqual(batch_plan(3, 1, 3), [1, 1, 1])

    def test_fewer_loaves_than_trays_with_remainder(self):
        # 2 loaves, 3 trays -> [1, 1, 0] (larger loads first)
        self.assertEqual(batch_plan(2, 1, 3), [1, 1, 0])

    def test_large_numbers(self):
        # 100 loaves, 5 trays -> [25, 25, 25, 25, 25]
        self.assertEqual(batch_plan(100, 1, 5), [25, 25, 25, 25, 25])

    def test_large_numbers_uneven(self):
        # 99 loaves, 5 trays -> [26, 25, 25, 25, 25] (larger loads first)
        self.assertEqual(batch_plan(99, 1, 5), [26, 25, 25, 25, 25])


if __name__ == '__main__':
    unittest.main()

