def distribute(total, parts):
    """
    Distribute total items into parts parts as evenly as possible.
    The first (total % parts) parts will have one more item than the others.
    Returns a list of parts integers summing to total.
    """
    if parts == 0:
        return []
    base = total // parts
    remainder = total % parts
    result = []
    for i in range(parts):
        if i < remainder:
            result.append(base + 1)
        else:
            result.append(base)
    return result
