from solution import nutrition_label


def test_basic_scale():
    """Test basic scaling of nutrients."""
    per_serving = {"milk": 50, "water": 100}
    servings = 2
    result = nutrition_label(per_serving, servings)
    assert result == {"milk": 50.0, "water": 10.0}


def test_single_serving():
    """Test scaling by 1 serving (no change)."""
    per_serving = {"milk": 50, "water": 100}
    servings = 1
    result = nutrition_label(per_serving, servings)
    assert result == {"milk": 50.0, "water": 100.0}


def test_empty_nutrients():
    """Test with empty nutrient dict."""
    per_serving = {}
    servings = 2
    result = nutrition_label(per_serving, servings)
    assert result == {}


def test_zero_serving():
    """Test scaling by 0 servings (all amounts become 0)."""
    per_serving = {"milk": 50, "water": 100}
    servings = 0
    result = nutrition_label(per_serving, servings)
    assert result == {"milk": 0.0, "water": 0.0}


