import unittest
import sys
import os

# Add the project root to the path so we can import from solution and lib
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from solution import nutrition_label


class TestNutritionLabel(unittest.TestCase):
    """Tests for nutrition_label function."""

    def test_scale_up(self):
        """Test scaling nutrients up by a positive factor."""
        per_serving = {"rice": 1.0, "cheese": 1.0}
        result = nutrition_label(per_serving, 3)
        self.assertEqual(result, {"rice": 1.2, "cheese": 1.2})

    def test_scale_down(self):
        """Test scaling nutrients down by a positive factor less than 1."""
        per_serving = {"rice": 3.0, "cheese": 3.0}
        result = nutrition_label(per_serving, 1)
        self.assertEqual(result, {"rice": 3.0, "cheese": 3.0})

    def test_rounding(self):
        """Test that results are rounded to 1 decimal place."""
        # 1.0 * 2 = 1.2 -> round to 1 decimal
        per_serving = {"rice": 1.0}
        result = nutrition_label(per_serving, 2)
        self.assertEqual(result, {"rice": 1.2})

        # 2.0 * 3 = 2.4 -> round to 1 decimal
        per_serving = {"rice": 2.0}
        result = nutrition_label(per_serving, 3)
        self.assertEqual(result, {"rice": 2.4})

    def test_empty_input(self):
        """Test with empty per_serving dict."""
        per_serving = {}
        result = nutrition_label(per_serving, 3)
        self.assertEqual(result, {})

    def test_non_dict_input_raises(self):
        """Test that non-dict per_serving raises TypeError."""
        with self.assertRaises(TypeError):
            nutrition_label("rice", 3)

    def test_negative_factor(self):
        """Test scaling by a negative factor (if supported)."""
        per_serving = {"rice": 1.0}
        result = nutrition_label(per_serving, -1)
        self.assertEqual(result, {"rice": -1.0})

    def test_multiple_nutrients(self):
        """Test scaling multiple nutrients."""
        per_serving = {"rice": 1.0, "cheese": 2.0, "butter": 0.5}
        result = nutrition_label(per_serving, 5)
        self.assertEqual(result, {"rice": 1.1, "cheese": 2.1, "butter": 0.5})

    def test_input_not_modified(self):
        """Test that the original per_serving dict is not modified."""
        per_serving = {"rice": 1.0}
        original_value = per_serving["rice"]
        nutrition_label(per_serving, 2)
        self.assertEqual(per_serving["rice"], original_value)


if __name__ == "__main__":
    unittest.main()

