import lib.quotakit as qa
from solution import request_space


def test_granted_when_exact_fit():
    """When used_mb + requested_mb == limit_mb, should grant."""
    assert request_space(0, 10, 10) == "granted"


def test_granted_when_under_limit():
    """When used_mb + requested_mb < limit_mb, should grant."""
    assert request_space(0, 5, 10) == "granted"


def test_denied_when_over_limit():
    """When used_mb + requested_mb > limit_mb, should deny."""
    assert request_space(0, 11, 10) == "denied"


def test_denied_when_used_exceeds_limit():
    """If used_mb alone exceeds limit, should deny (even if requested is 0)."""
    assert request_space(11, 0, 10) == "denied"


def test_granted_with_zero_requested():
    """If requested_mb is 0 and used_mb <= limit, should grant."""
    assert request_space(5, 0, 10) == "granted"


def test_denied_with_zero_requested_when_used_exceeds():
    """If requested_mb is 0 and used_mb > limit, should deny."""
    assert request_space(11, 0, 10) == "denied"


def test_granted_with_zero_used():
    """If used_mb is 0 and requested_mb <= limit, should grant."""
    assert request_space(0, 10, 10) == "granted"


def test_denied_with_zero_used_when_requested_exceeds():
    """If used_mb is 0 and requested_mb > limit, should deny."""
    assert request_space(0, 11, 10) == "denied"

