import unittest
import sys
import os

# Add the lib directory to the path so we can import toolpath
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'lib'))

from solution import job_label, batch_seconds
from lib.toolpath import estimate_seconds


class TestJobLabel(unittest.TestCase):
    def test_simple_job(self):
        job = {'name': 'test_job', 'length_mm': 100, 'feed_mm_min': 10}
        # estimate_seconds(100, 10) = 100 / 10 * 60 = 100 * 60 = 600 (rounded)
        expected_time = estimate_seconds(100, 10)
        self.assertEqual(job_label(job), f"test_job: {expected_time}s")

    def test_job_with_custom_accel(self):
        # This test is to verify the logic handles the default accel_factor correctly
        # Since we can't change the function signature, we test with values that 
        # would result in different times if accel_factor were different
        job = {'name': 'fast_job', 'length_mm': 50, 'feed_mm_min': 10}
        expected_time = estimate_seconds(50, 10)
        self.assertEqual(job_label(job), f"fast_job: {expected_time}s")

    def test_job_with_zero_length(self):
        job = {'name': 'empty_job', 'length_mm': 0, 'feed_mm_min': 10}
        expected_time = estimate_seconds(0, 10)
        self.assertEqual(job_label(job), f"empty_job: {expected_time}s")

    def test_job_with_large_values(self):
        job = {'name': 'big_job', 'length_mm': 1000, 'feed_mm_min': 10}
        expected_time = estimate_seconds(1000, 10)
        self.assertEqual(job_label(job), f"big_job: {expected_time}s")


class TestBatchSeconds(unittest.TestCase):
    def test_empty_batch(self):
        self.assertEqual(batch_seconds([]), 0)

    def test_single_job(self):
        jobs = [{'name': 'single', 'length_mm': 100, 'feed_mm_min': 10}]
        expected = estimate_seconds(100, 10)
        self.assertEqual(batch_seconds(jobs), expected)

    def test_multiple_jobs(self):
        jobs = [
            {'name': 'job1', 'length_mm': 100, 'feed_mm_min': 10},
            {'name': 'job2', 'length_mm': 50, 'feed_mm_min': 10}
        ]
        expected = estimate_seconds(100, 10) + estimate_seconds(50, 10)
        self.assertEqual(batch_seconds(jobs), expected)

    def test_jobs_with_different_feed_times(self):
        jobs = [
            {'name': 'fast', 'length_mm': 50, 'feed_mm_min': 10},
            {'name': 'slow', 'length_mm': 100, 'feed_mm_min': 100}
        ]
        expected = estimate_seconds(50, 10) + estimate_seconds(100, 100)
        self.assertEqual(batch_seconds(jobs), expected)


if __name__ == '__main__':
    unittest.main()

