def test_empty_reviews():
    """Test with an empty list of reviews."""
    result = review_summary([])
    assert result == {'approved': 0, 'changes_requested': 0, 'commented': 0, 'total': 0}


def test_single_approved_review():
    """Test with a single approved review."""
    reviews = [{'status': 'approved'}]
    result = review_summary(reviews)
    assert result == {'approved': 1, 'changes_requested': 0, 'commented': 0, 'total': 1}


def test_single_changes_requested_review():
    """Test with a single changes_requested review."""
    reviews = [{'status': 'changes_requested'}]
    result = review_summary(reviews)
    assert result == {'approved': 0, 'changes_requested': 1, 'commented': 0, 'total': 1}


def test_single_commented_review():
    """Test with a single commented review."""
    reviews = [{'status': 'commented'}]
    result = review_summary(reviews)
    assert result == {'approved': 0, 'changes_requested': 0, 'commented': 1, 'total': 1}


def test_mixed_reviews():
    """Test with a mix of different review statuses."""
    reviews = [
        {'status': 'approved'},
        {'status': 'approved'},
        {'status': 'changes_requested'},
        {'status': 'commented'},
        {'status': 'commented'},
        {'status': 'commented'},
    ]
    result = review_summary(reviews)
    assert result == {'approved': 2, 'changes_requested': 1, 'commented': 3, 'total': 6}


def test_unknown_status_is_counted_in_total():
    """Test that an unknown status is still counted in total but not in specific categories."""
    reviews = [{'status': 'unknown_status'}]
    result = review_summary(reviews)
    assert result == {'approved': 0, 'changes_requested': 0, 'commented': 0, 'total': 1}


def test_multiple_unknown_statuses():
    """Test multiple unknown statuses are all counted in total."""
    reviews = [
        {'status': 'unknown1'},
        {'status': 'unknown2'},
    ]
    result = review_summary(reviews)
    assert result == {'approved': 0, 'changes_requested': 0, 'commented': 0, 'total': 2}

