def review_summary(reviews):
    """
    Returns a summary of code review statuses.

    Args:
        reviews: A list of dicts each having a 'status' key.

    Returns:
        A dict with counts for 'approved', 'changes_requested', 'commented', and 'total'.
    """
    counts = {
        'approved': 0,
        'changes_requested': 0,
        'commented': 0,
        'total': len(reviews)
    }

    for review in reviews:
        status = review.get('status')
        if status == 'approved':
            counts['approved'] += 1
        elif status == 'changes_requested':
            counts['changes_requested'] += 1
        elif status == 'commented':
            counts['commented'] += 1

    return counts

