def format_row(values, sep=','):
    """
    Converts each value with str() and wraps a cell in double quotes if it contains sep, a double quote or a newline.
    Doubles any inner double quotes.
    Joins the cells with sep.
    """
    cells = []
    for value in values:
        cell = str(value)
        if sep in cell or '"' in cell or '\n' in cell:
            # Escape double quotes by doubling them
            cell = cell.replace('"', '""')
            cell = '"' + cell + '"'
        cells.append(cell)
    return sep.join(cells)


