from lib.pickeroute import plan_picks


def dispatch_picks(order, slot_map):
    # Convert order list to dict for plan_picks if needed
    # plan_picks expects a dict mapping sku to qty
    if isinstance(order, list):
        order_dict = {}
        for item in order:
            sku = item['sku']
            qty = item['qty']
            if qty > 0:
                order_dict[sku] = qty
    else:
        order_dict = order

    return plan_picks(order_dict, slot_map)

