class TestDispatchPicks(unittest.TestCase):
    def test_empty_order(self):
        """Test with an empty order list."""
        result = dispatch_picks([], {})
        self.assertEqual(result, [])

    def test_no_positive_quantities(self):
        """Test with order containing only non-positive quantities."""
        order = [{'sku': 'A', 'qty': 0}, {'sku': 'B', 'qty': -1}]
        result = dispatch_picks(order, {})
        self.assertEqual(result, [])

    def test_single_sku_with_slot(self):
        """Test a single SKU with provided slot map."""
        order = [{'sku': 'A', 'qty': 1}]
        slot_map = {'A': ('AA', '01')}
        result = dispatch_picks(order, slot_map)
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0], {'sku': 'A', 'qty': 1, 'aisle': 'AA', 'shelf': '01'})

    def test_single_sku_without_slot(self):
        """Test a single SKU not in slot map defaults to ('ZZ', '00')."""
        order = [{'sku': 'A', 'qty': 1}]
        result = dispatch_picks(order, {})
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0], {'sku': 'A', 'qty': 1, 'aisle': 'ZZ', 'shelf': '00'})

    def test_multiple_skus_sorted(self):
        """Test multiple SKUs sorted by aisle, shelf, sku."""
        order = [
            {'sku': 'C', 'qty': 1},
            {'sku': 'A', 'qty': 1},
            {'sku': 'B', 'qty': 1}
        ]
        slot_map = {
            'A': ('BB', '00'),
            'B': ('AA', '00'),
            'C': ('AA', '01')
        }
        result = dispatch_picks(order, slot_map)
        # Expected order: B (AA, 00), C (AA, 01), A (BB, 00)
        expected = [
            {'sku': 'B', 'qty': 1, 'aisle': 'AA', 'shelf': '00'},
            {'sku': 'C', 'qty': 1, 'aisle': 'AA', 'shelf': '01'},
            {'sku': 'A', 'qty': 1, 'aisle': 'BB', 'shelf': '00'}
        ]
        self.assertEqual(result, expected)

    def test_mixed_quantities_and_missing_slots(self):
        """Test mixed quantities and SKUs not in slot map."""
        order = [
            {'sku': 'A', 'qty': 1},
            {'sku': 'B', 'qty': 0},
            {'sku': 'C', 'qty': 1}
        ]
        slot_map = {'A': ('ZZ', '01')}  # C not in slot_map
        result = dispatch_picks(order, slot_map)
        # B is filtered out (qty=0), A and C remain
        # A: ZZ, 01; C: ZZ, 00
        expected = [
            {'sku': 'C', 'qty': 1, 'aisle': 'ZZ', 'shelf': '00'},
            {'sku': 'A', 'qty': 1, 'aisle': 'ZZ', 'shelf': '01'}
        ]
        self.assertEqual(result, expected)

    def test_duplicate_skus(self):
        """Test duplicate SKUs in order."""
        order = [
            {'sku': 'A', 'qty': 1},
            {'sku': 'A', 'qty': 2}
        ]
        slot_map = {}
        result = dispatch_picks(order, slot_map)
        # Both A entries should be included as separate instructions
        self.assertEqual(len(result), 2)
        self.assertIn({'sku': 'A', 'qty': 1, 'aisle': 'ZZ', 'shelf': '00'}, result)
        self.assertIn({'sku': 'A', 'qty': 2, 'aisle': 'ZZ', 'shelf': '00'}, result)


