import unittest
from solution import dispatch_picks


class TestDispatchPicks(unittest.TestCase):
    def test_empty_order(self):
        """Test with an empty order list."""
        slot_map = {}
        order = []
        result = dispatch_picks(order, slot_map)
        self.assertEqual(result, [])

    def test_filters_non_positive_quantities(self):
        """Test that non-positive quantities are filtered out."""
        slot_map = {}
        order = [
            ('SKU_A', 5),
            ('SKU_B', 0),
            ('SKU_C', -1),
            ('SKU_D', 1),
        ]
        result = dispatch_picks(order, slot_map)
        expected = [
            {'sku': 'SKU_A', 'qty': 5, 'aisle': 'ZZ', 'shelf': '00'},
            {'sku': 'SKU_D', 'qty': 1, 'aisle': 'ZZ', 'shelf': '00'},
        ]
        self.assertEqual(result, expected)

    def test_uses_slot_map_for_aisle_shelf(self):
        """Test that slot_map values are used for aisle and shelf."""
        slot_map = {
            'SKU_A': ('AA', '01'),
            'SKU_B': ('BB', '02'),
        }
        order = [
            ('SKU_A', 5),
            ('SKU_B', 3),
        ]
        result = dispatch_picks(order, slot_map)
        expected = [
            {'sku': 'SKU_A', 'qty': 5, 'aisle': 'AA', 'shelf': '01'},
            {'sku': 'SKU_B', 'qty': 3, 'aisle': 'BB', 'shelf': '02'},
        ]
        self.assertEqual(result, expected)

    def test_sorts_by_aisle_then_shelf_then_sku(self):
        """Test sorting by aisle, shelf, then sku."""
        slot_map = {
            'SKU_C': ('BB', '02'),
            'SKU_A': ('AA', '01'),
            'SKU_B': ('AA', '00'),
        }
        order = [
            ('SKU_C', 1),
            ('SKU_A', 1),
            ('SKU_B', 1),
        ]
        result = dispatch_picks(order, slot_map)
        expected = [
            {'sku': 'SKU_B', 'qty': 1, 'aisle': 'AA', 'shelf': '00'},
            {'sku': 'SKU_A', 'qty': 1, 'aisle': 'AA', 'shelf': '01'},
            {'sku': 'SKU_C', 'qty': 1, 'aisle': 'BB', 'shelf': '02'},
        ]
        self.assertEqual(result, expected)

    def test_handles_missing_sku_in_slot_map(self):
        """Test that missing SKU in slot_map defaults to ('ZZ', '00')."""
        slot_map = {
