def draft_overall_pick(text, teams=32, default=None):
    # Handle None, non-string, or empty/whitespace-only strings
    if text is None or not isinstance(text, str) or text.strip() == '':
        return default

    # Strip whitespace
    text = text.strip()

    # Check if it matches the expected format: digits.digits
    parts = text.split('.')
    if len(parts) != 2:
        raise ValueError(f"Invalid format: {text!r}. Expected 'round.pick'")

    round_no, pick_no = parts

    # Check if both parts are valid integers (digits)
    if not round_no.isdigit() or not pick_no.isdigit():
        raise ValueError(f"Invalid format: {text!r}. Round and pick must be digits.")

    # Calculate the overall pick number
    return (int(round_no) - 1) * teams + int(pick_no)

