    # Return default for None, non-string, or empty/whitespace-only strings
    if text is None or not isinstance(text, str) or not text.strip():
        return default

    # Strip whitespace
    text = text.strip()

    # Split by '.'
    parts = text.split('.')

    # Must have exactly two parts
    if len(parts) != 2:
        raise ValueError(f"Invalid draft slot format: '{text}'. Expected 'round.pick'")

    round_no, pick_no = parts

    # Check if both parts are non-empty and consist only of digits
    if not round_no or not pick_no:
        raise ValueError(f"Invalid draft slot format: '{text}'. Round and pick must be non-empty digit strings.")

    if not round_no.isdigit() or not pick_no.isdigit():
        raise ValueError(f"Invalid draft slot format: '{text}'. Round and pick must be digit strings.")

