    if not isinstance(label, str):
        return default

    # Handle empty or whitespace-only strings
    s = label.strip()
    if not s:
        return default

    # Check for colon separator
    if ':' in s:
        # Split by colon and take the last part
        num = s.split(':')[-1].strip()
    else:
        # No colon: try to find the first token that might be numeric
        # We need to find the first numeric-looking token or just the first token
        parts = s.split()
        if not parts:
            return default
        # Try to find the first token that is purely numeric
        num = None
        for part in parts:
            try:
                int(part)
                num = part
                break
            except ValueError:
                continue
        if num is None:
            # If no numeric token found, return default
            return default

    # If after stripping, the num is empty, return default
    if not num:
        return default

    try:
        return int(num)
    except ValueError:
